class MinStack:
    def __init__(self):
        self.st = []; self.min = []
    def push(self, v):
        self.st.append(v)
        if not self.min or v <= self.min[-1]:
            self.min.append(v)
    def pop(self):
        if self.st:
            if self.st[-1]==self.min[-1]: self.min.pop()
            self.st.pop()
    def getMin(self):
        return self.min[-1]
